typedef float time_value_t;
typedef unsigned size_t;

extern "C" char *strncpy(char *, const char *, size_t);

class stringx
{
public:
  const char *c_str() const;
};

template<class T> class vector
{
  T *begin_;
  T *end_;
  T *capacity_;
public:
  unsigned size() const { return end_ - begin_; }
  T& operator[](unsigned i) { return begin_[i]; }
  void push_back(const T& value);
};

#define MESSAGE_STRING_LENGTH 100

class message_board
{
public:
  message_board();
  void post(stringx s, time_value_t time);
  void frame_advance(time_value_t time_inc);
  void render();
private:
  struct message
  {
    char text[MESSAGE_STRING_LENGTH];
    time_value_t time;
  };
  vector<message> messages;
};

void message_board::post(stringx s, time_value_t time )
{
#if !defined(BUILD_BOOTABLE) && !defined(BUILD_RELEASE)
  unsigned i;
  for (i=0;i<messages.size();++i)
  {
    if (messages[i].time==0) 
      break;
  }
  message msg;
  strncpy(msg.text,s.c_str(),MESSAGE_STRING_LENGTH-1);
  msg.time = time;

  if (i==messages.size())
    messages.push_back(msg);
  else
    messages[i] = msg;
#endif
}
